        rows = []
        for i in range(1, n + 1):
            counts = [0, 0, 0]
            for j in range(1, n + 1):
                counts[(i + 2 * j) % 3] += 1
            rows.append(tuple(counts))

        cols = []
        for j in range(1, n + 1):
            counts = [0, 0, 0]
            for i in range(1, n + 1):
                counts[(i + 2 * j) % 3] += 1
            cols.append(tuple(counts))

        all_types = rows + cols

        possible_sums = set()
        possible_sums.add((0, 0, 0))
        for v in all_types:
            new_sums = set()
            for s in possible_sums:
                new_sums.add((s[0] + v[0], s[1] + v[1], s[2] + v[2]))
            possible_sums.update(new_sums)

        found = False
        for s in possible_sums:
            if s == (0, 0, 0):
                continue
            if s[0] == s[1] == s[2]:
                found = True
                break
        results.append(found)
    return results

