def solve_bfs_n3():
    n = 3
    # State is a bitmask of n*n = 9 bits
    # Moves:
    # 1. Add tromino L_{i,j} = {(i,j), (i+1,j), (i,j+1)}
    # 2. Remove row i if full
    # 3. Remove col j if full

    # Precompute masks
    tromino_masks = []
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            m = 0
            cells = [(i, j), (i+1, j), (i, j+1)]
            possible = True
            for r, c in cells:
                if 1 <= r <= n and 1 <= c <= n:
                    m |= (1 << ((r - 1) * n + (c - 1)))
                else:
                    possible = False
                    break
            if possible:
                tromino_masks.append(m)

    row_masks = []
    for i in range(1, n + 1):
        m = 0
        for j in range(1, n + 1):
            m |= (1 << ((i - 1) * n + (j - 1)))
        row_masks.append(m)

    col_masks = []
    for j in range(1, n + 1):
        m = 0
        for i in range(1, n + 1):
            m |= (1 << ((i - 1) * n + (j - 1)))
        col_masks.append(m)

    # BFS
    start_mask = 0
    queue = [(start_mask, 0)]
    visited = {start_mask}

    idx = 0
    while idx < len(queue):
        mask, moves = queue[idx]
        idx += 1

        # Add tromino
        for tm in tromino_masks:
            if (mask & tm) == 0:
                new_mask = mask | tm
                if new_mask == 0: # should not happen
                    return True
                if new_mask not in visited:
                    visited.add(new_mask)
                    queue.append((new_mask, moves + 1))

        # Remove row
        for rm in row_masks:
            if (mask & rm) == rm:
                new_mask = mask & ~rm
                if new_mask == 0:
                    return True
                if new_mask not in visited:
                    visited.add(new_mask)
                    queue.append((new_mask, moves + 1))

        # Remove col
        for cm in col_masks:
            if (mask & cm) == cm:
                new_mask = mask & ~cm
                if new_mask == 0:
                    return True
                if new_mask not in visited:
                    visited.add(new_mask)
                    queue.append((new_mask, moves + 1))
    return False

print(solve_bfs_n3())

